// ========== Search overlay + settings panel nav sync (was shell_scripts.search_overlay_markup) ==========
(function () {
  if (window.__adminShellSearchInit) return;
  window.__adminShellSearchInit = 1;
  var searchResults = document.getElementById('search-results');
  var searchFocusedIndex = -1;

  document.addEventListener('click', function (e) {
    var results = document.getElementById('search-results');
    if (!results) return;
    var searchInput = document.querySelector('[hx-get$="/search"]');
    if (results.children.length > 0 &&
        !results.contains(e.target) &&
        (!searchInput || !searchInput.contains(e.target))) {
      results.innerHTML = '';
      searchFocusedIndex = -1;
    }
  });

  document.addEventListener('keydown', function (e) {
    var results = document.getElementById('search-results');
    if (!results || results.children.length === 0) return;

    var items = results.querySelectorAll('.search-result-item');
    if (items.length === 0) return;

    // Escape closes search
    if (e.key === 'Escape') {
      results.innerHTML = '';
      searchFocusedIndex = -1;
      return;
    }

    // Arrow down
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      searchFocusedIndex = Math.min(searchFocusedIndex + 1, items.length - 1);
      items[searchFocusedIndex].focus();
      return;
    }

    // Arrow up
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      searchFocusedIndex = Math.max(searchFocusedIndex - 1, 0);
      items[searchFocusedIndex].focus();
      return;
    }
  });

  // Loading indicator via HTMX events
  document.addEventListener('htmx:beforeRequest', function (e) {
    var searchInput = e.detail && e.detail.elt ? e.detail.elt.closest('[hx-get*="/search"]') : null;
    if (!searchInput) return;
    var results = document.getElementById('search-results');
    if (!results) return;
    results.innerHTML = '<div class="search-loading text-center py-8 px-4 text-sm text-muted-foreground">Searching...</div>';
    searchFocusedIndex = -1;
  });

  document.addEventListener('htmx:afterRequest', function (e) {
    var searchInput = e.detail && e.detail.elt ? e.detail.elt.closest('[hx-get*="/search"]') : null;
    if (!searchInput) return;
    var results = document.getElementById('search-results');
    if (!results) return;
    if (!results.querySelector('.search-results, .search-results-empty')) {
      results.innerHTML = '';
    }
  });

  document.addEventListener('htmx:beforeSwap', function (e) {
    var searchInput = e.detail && e.detail.elt ? e.detail.elt.closest('[hx-get*="/search"]') : null;
    if (searchInput) {
      searchFocusedIndex = -1;
    }
  });

  // SPA navigation is owned by window.OrideconNavigator (see the navigator
  // section below): plain same-origin link clicks route through it, and it
  // owns abort/title/scroll/focus/history. Delegation below survives body
  // swaps because the navigator is registered as a document-level listener.

  // Keep contributor settings links truthful when a panel swaps only the
  // Configuration Center content column. The sidebar survives the swap, so
  // update its active styling from the URL rather than asking every panel
  // handler to know about layout markup. Delegation keeps this alive across
  // body swaps.
  function syncSettingsPanelNavigation(path) {
    var currentPath;
    try {
      currentPath = new URL(path || location.href, location.href).pathname;
    } catch (err) {
      currentPath = location.pathname;
    }
    currentPath = currentPath.length > 1
      ? currentPath.replace(new RegExp('/+$'), '')
      : currentPath;

    document.querySelectorAll('[data-settings-panel-nav]').forEach(function (link) {
      var linkPath;
      try {
        linkPath = new URL(link.href, location.href).pathname;
      } catch (err) {
        return;
      }
      linkPath = linkPath.length > 1
        ? linkPath.replace(new RegExp('/+$'), '')
        : linkPath;
      var active = linkPath === currentPath;
      [
        'bg-primary-50', 'text-primary-700',
        'dark:bg-primary-900/30', 'dark:text-primary-400',
        'font-medium'
      ].forEach(function (className) {
        link.classList.toggle(className, active);
      });
      [
        'text-muted-foreground', 'hover:bg-muted',
        'dark:text-muted-foreground', 'dark:hover:bg-card'
      ].forEach(function (className) {
        link.classList.toggle(className, !active);
      });
      if (active) {
        link.setAttribute('aria-current', 'page');
      } else {
        link.removeAttribute('aria-current');
      }
    });
  }

  document.addEventListener('htmx:pushedIntoHistory', function (e) {
    var path = e.detail && e.detail.path;
    syncSettingsPanelNavigation(path || location.href);
  });
  document.addEventListener('htmx:historyRestore', function () {
    syncSettingsPanelNavigation(location.href);
  });
  window.addEventListener('popstate', function () {
    window.setTimeout(function () {
      syncSettingsPanelNavigation(location.href);
    }, 0);
  });
  window.setTimeout(function () {
    syncSettingsPanelNavigation(location.href);
  }, 0);
})();

